content.css:
/* store layout shared by the designed pages */
.eh-home,.ec-shop,.ec-cart,.ec-order-page{max-width:var(--wide-width,1200px);margin:0 auto;padding:0 1.5rem}
.ec-product-card__media img{aspect-ratio:4/5;object-fit:cover;background:var(--color-bg-subtle,#f5f5f5)}
.ec-product-card__title a{text-decoration:none;color:var(--color-text,#1a1a1a)}
.ec-product-card__title a:hover{color:var(--color-brand,#0066cc)}
.ec-add-to-cart,.ec-add-to-cart--link{border-radius:6px}
.ec-shop__header{margin-top:2rem}
.ec-cart,.ec-order-page{padding-top:2rem;padding-bottom:4rem}
.ec-cart h1{margin-top:0}
